async function main() {
  console.log('🌱 Seeding database with Indian colleges...');

  for (const data of collegesData) {
    const { courses, placement, ...collegeData } = data;

    const college = await prisma.college.upsert({
      where: { slug: collegeData.slug },
      update: {},
      create: {
        ...collegeData,
        courses: {
          create: courses,
        },
        placement: {
          create: placement,
        },
      },
    });

    console.log(`✅ ${college.name}`);
  }

  console.log(`\n🎉 Seeded ${collegesData.length} colleges successfully!`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
